import React from "react"
import _ from "lodash"
import styled from "styled-components"

const RelativeWrapper = styled.div`
  position: relative;
`

const Wrapper = styled.aside`
  position: absolute;
  left: 112%;
  top: 0px;
  width: 200px;
  height: 100px;
  font-size: 16px;

  @media (max-width: 1300px) {
    display: none;
  }
`

const Title = styled.div`
  margin-bottom: 25px;
  font-weight: bold;
  color: ${props => props.theme?.colors?.secondaryText || '#666'};
`

const Tag = styled.li`
  margin-bottom: 16px;
  color: ${props => props.selected 
    ? props.theme?.colors?.text || '#333'
    : props.theme?.colors?.tertiaryText || '#999'
  };
  cursor: pointer;
  transition: color 0.3s;
  font-weight: ${props => props.selected ? 'bold' : 'normal'};

  &:hover {
    color: ${props => props.theme?.colors?.text || '#333'};
  }
`

const SideTagList = ({ tagList, selectedTag, onClick }) => {
  const totalPosts = tagList ? tagList.reduce((sum, tag) => sum + tag.totalCount, 0) : 0
  
  return (
    <RelativeWrapper>
      <Wrapper>
        <Title>TAG LIST</Title>
        <ul>
          <Tag 
            selected={!selectedTag}
            onClick={() => onClick(null)}
          >
            모든 태그 ({totalPosts})
          </Tag>
          {tagList && _.map(tagList, tag => (
            <Tag 
              key={tag.fieldValue}
              selected={selectedTag === tag.fieldValue}
              onClick={() => onClick(tag.fieldValue)}
            >
              {tag.fieldValue} ({tag.totalCount})
            </Tag>
          ))}
        </ul>
      </Wrapper>
    </RelativeWrapper>
  )
}

export default SideTagList
